import { ThemeProvider } from "./context/ThemeContext";
import ThemeToggle from "./components/ThemeToggle";
import StatusBadge from "./components/StatusBadge";

// Centralised footer labels — single source of truth
const FOOTER_LABELS = [
  "Wave C Deep Eco Check",
  "Production Build",
  "Run 7",
] as const;

const CHECKS = [
  { label: "Environmental Impact", value: 94, color: "bg-emerald-400" },
  { label: "Carbon Footprint",     value: 81, color: "bg-teal-400"    },
  { label: "Resource Efficiency",  value: 88, color: "bg-cyan-400"    },
  { label: "Waste Reduction",      value: 76, color: "bg-green-400"   },
];

const TAGS = ["Wave C", "Deep Eco", "Verified", "Safe", "Sustainable"];

function AnimatedBar({
  value,
  color,
  delay,
  label,
}: {
  value: number;
  color: string;
  delay: number;
  label: string;
}) {
  const [width, setWidth] = useState(0);

  useEffect(() => {
    const timer = setTimeout(() => setWidth(value), 300 + delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return (
    <div
      className="h-2 w-full rounded-full overflow-hidden"
      style={{ background: "rgba(255,255,255,0.10)" }}
      role="progressbar"
      aria-valuenow={width}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-label={label}
    >
      <div
        className={`h-full ${color} rounded-full transition-all duration-1000 ease-out`}
        style={{ width: `${width}%` }}
      />
    </div>
  );
}

function AppContent() {
  const [mounted, setMounted] = useState(false);
  const [counter, setCounter] = useState(0);

  useEffect(() => {
    setMounted(true);
    let frame = 0;
    let start: number | null = null;
    const target = 98;
    const duration = 1800;

    const tick = (ts: number) => {
      if (!start) start = ts;
      const elapsed = ts - start;
      const progress = Math.min(elapsed / duration, 1);
      setCounter(Math.round(progress * target));
      if (progress < 1) frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, []);

  return (
    <div
      className="min-h-screen flex flex-col px-4 py-6 overflow-hidden relative"
      style={{ background: "var(--color-bg)" }}
    >
