        style={{ background: "var(--color-bg-card)", color: "var(--color-text-primary)" }}
      >
        Skip to content
      </a>

      {/* Background orbs */}
      <div
        className="absolute top-[-10%] left-[-5%] w-72 h-72 rounded-full blur-3xl pointer-events-none"
        style={{ background: "var(--color-orb-a)" }}
        aria-hidden="true"
      />
      <div
        className="absolute bottom-[-10%] right-[-5%] w-96 h-96 rounded-full blur-3xl pointer-events-none"
        style={{ background: "var(--color-orb-b)" }}
        aria-hidden="true"
      />
      <div
        className="absolute top-[40%] left-[60%] w-48 h-48 rounded-full blur-2xl pointer-events-none"
        style={{ background: "var(--color-orb-c)" }}
        aria-hidden="true"
      />

      {/* Header */}
      <header className="relative z-10 flex justify-end mb-6">
        <ThemeToggle />
      </header>

      {/* Main content */}
      <main
        id="main-content"
        className="relative z-10 flex-1 flex items-center justify-center"
      >
        <div
          className={`text-center max-w-2xl w-full transition-all duration-700 ease-out ${
            mounted ? "opacity-100 translate-y-0" : "opacity-0 translate-y-8"
          }`}
        >
          {/* Glassmorphism card */}
          <div
            className="backdrop-blur-md rounded-3xl px-8 py-12 shadow-2xl"
            style={{
              background: "var(--color-bg-card)",
              border: "1px solid var(--color-border)",
            }}
          >
            {/* Score ring */}
            <div className="flex justify-center mb-8">
              <div className="relative flex items-center justify-center w-24 h-24">
                <svg
                  className="absolute inset-0 w-full h-full -rotate-90"
                  viewBox="0 0 96 96"
                  role="img"
                  aria-label={`Eco score: ${counter}%`}
                >
                  <circle
                    cx="48" cy="48" r="44"
                    fill="none"
                    stroke="rgba(255,255,255,0.08)"
                    strokeWidth="6"
                  />
                  <circle
                    cx="48" cy="48" r="44"
                    fill="none"
                    stroke="url(#ecoGrad)"
                    strokeWidth="6"
                    strokeLinecap="round"
                    strokeDasharray={`${2 * Math.PI * 44}`}
                    strokeDashoffset={`${2 * Math.PI * 44 * (1 - counter / 100)}`}
                    className="transition-all duration-200"
                  />
                  <defs>
                    <linearGradient id="ecoGrad" x1="0%" y1="0%" x2="100%" y2="0%">
                      <stop offset="0%" stopColor="#34d399" />
                      <stop offset="100%" stopColor="#22d3ee" />
                    </linearGradient>
                  </defs>
                </svg>
                <span
                  className="relative z-10 text-2xl font-extrabold tabular-nums"
                  style={{ color: "var(--color-text-primary)" }}
                >
                  {counter}
                  <span className="text-sm font-bold text-emerald-300">%</span>
                </span>
              </div>
            </div>

            {/* Main heading */}
            <h1
              className="text-4xl sm:text-5xl md:text-6xl font-bold tracking-tight leading-tight mb-3"
              style={{ color: "var(--color-text-primary)" }}
            >
              Wave C Deep{" "}
              <span className="bg-gradient-to-r from-emerald-300 to-cyan-300 bg-clip-text text-transparent">
                Eco Check
              </span>
            </h1>

            {/* Divider */}
            <div className="flex items-center justify-center gap-3 my-5" aria-hidden="true">
              <div className="h-px w-16 rounded" style={{ background: "var(--color-border)" }} />
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-400/60" />
              <div className="h-px w-16 rounded" style={{ background: "var(--color-border)" }} />
            </div>

            {/* Subtitle */}
            <p
              className="text-lg sm:text-xl font-medium tracking-wide mb-8"
              style={{ color: "var(--color-text-label)" }}
            >
              Safe planning verified.
            </p>

            {/* Metric bars */}
            <div className="space-y-4 text-left mb-8">
              {CHECKS.map((c, i) => (
                <div key={c.label}>
                  <div className="flex justify-between items-center mb-1.5">
                    <span
                      className="text-sm font-medium"
                      style={{ color: "var(--color-text-secondary)" }}
                    >
                      {c.label}
                    </span>
                    <span
                      className="text-sm font-semibold tabular-nums"
                      style={{ color: "var(--color-text-muted)" }}
                    >
                      {c.value}%
                    </span>
                  </div>
                  <AnimatedBar
                    value={c.value}
                    color={c.color}
                    delay={i * 150}
                    label={`${c.label}: ${c.value}%`}
                  />
                </div>
              ))}
            </div>

            {/* Tags */}
            <div className="flex flex-wrap justify-center gap-2">
              {TAGS.map((tag) => (
                <span
                  key={tag}
                  className="px-3 py-1 rounded-full text-xs font-semibold cursor-default select-none"
                  style={{
                    background: "rgba(255,255,255,0.08)",
                    border: "1px solid var(--color-border)",
                    color: "var(--color-text-label)",
                  }}
                >
                  {tag}
                </span>
              ))}
            </div>
          </div>

          {/* Footer */}
          <footer
            className="mt-6"
            aria-label="Page footer"
          >
            {/* Top border rule */}
            <div
              className="h-px w-full mb-4"
              style={{ background: "var(--color-border)" }}
              aria-hidden="true"
            />

            {/* Unified footer labels — single source array */}
            <div className="flex flex-wrap justify-center items-center gap-x-4 gap-y-1 mb-4">
              {FOOTER_LABELS.map((label, i) => (
                <span
                  key={label}
                  className="text-xs font-medium tracking-widest uppercase"
                  style={{ color: "var(--color-text-muted)" }}
                >
